#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# 测试机的引导（#14）：在测试机上用 root 运行。
#   curl -fsSLo test-machine.sh https://raw.githubusercontent.com/bilixuesheng/SeekCloud/main/scripts/test-machine.sh
#   sudo bash test-machine.sh
# 检查是不是完整的虚拟机，装 Docker Engine 和 Sysbox，把沙箱的存储放到开了项目配额的 XFS 上（#168），
# 自检，再注册成本仓库的 GitHub 自托管 Runner。
# 可以重复运行：做过的步骤会跳过。

REPO="bilixuesheng/SeekCloud"
SYSBOX_VERSION="0.7.1"
SYSBOX_URL="https://downloads.nestybox.com/sysbox/releases/v${SYSBOX_VERSION}/sysbox-ce_${SYSBOX_VERSION}-0.linux_amd64.deb"
SYSBOX_SHA256="9d6d5484f980d0a17f86c492c1262015c2afb66280bdb97215b79fde6a0261c5"
RUNNER_USER="seekcloud-runner"
RUNNER_DIR="/home/${RUNNER_USER}/actions-runner"
SELFTEST="seekcloud-selftest"
ENV_FILE="/root/.seekcloud-test-machine.env"

if [[ $EUID -ne 0 ]]; then
  echo "请用 root 运行：sudo bash $0"
  exit 1
fi
# apt 不弹交互式的窗口（Ubuntu 的 needrestart 会问重启哪些服务）
export DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a

refund_hint() {
  warn "这台机器用不了。请在 24 小时内到小兔互联的控制台提交工单申请退款。"
  warn "不要点\"停用\"或\"删除\"：那会直接删掉服务器，就退不了款了。"
}

TOTAL_STAGES=7

banner "SeekCloud 测试机：Docker、Sysbox 和 GitHub Runner"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "检查这台机器是不是完整的虚拟机"
say "Sysbox 要完整的虚拟机（KVM 一类），容器式的 VPS（LXC、OpenVZ）装不了。"
ok=1
container=$(systemd-detect-virt --container 2>/dev/null || true)
virt=$(systemd-detect-virt 2>/dev/null || true)
if [[ -n "$container" && "$container" != "none" ]]; then
  warn "这是容器式的 VPS（$container），不是完整的虚拟机。"; ok=0
else
  step "虚拟化：${virt:-未知}（不是容器，可以）"
fi
arch=$(uname -m)
if [[ "$arch" == "x86_64" ]]; then step "架构：$arch"; else warn "架构是 $arch，Sysbox 的安装包只有 x86_64"; ok=0; fi
# shellcheck disable=SC1091
. /etc/os-release
if [[ "${ID:-}" == "ubuntu" && ( "${VERSION_ID:-}" == "24.04" || "${VERSION_ID:-}" == "22.04" ) ]]; then
  step "系统：${PRETTY_NAME:-$ID $VERSION_ID}"
else
  warn "系统是 ${PRETTY_NAME:-未知}。请在控制台把系统重装成 Ubuntu 24.04 再运行。"; ok=0
fi
kernel=$(uname -r); kmaj=${kernel%%.*}; krest=${kernel#*.}; kmin=${krest%%.*}
if (( kmaj > 5 || (kmaj == 5 && kmin >= 19) )); then step "内核：$kernel"
elif (( kmaj == 5 && kmin >= 12 )); then step "内核：$kernel（能用，5.19 以上更好）"
else warn "内核 $kernel 太旧，Sysbox 要 5.12 以上"; ok=0; fi
if [[ "$(ps -p 1 -o comm= 2>/dev/null)" == "systemd" ]]; then step "进程管理：systemd"; else warn "1 号进程不是 systemd"; ok=0; fi
cpus=$(nproc); mem=$(free -m | awk '/^Mem:/{print $2}'); disk=$(df -BG --output=avail / | tail -1 | tr -dc '0-9')
step "CPU ${cpus} 核，内存 ${mem} MB，硬盘剩 ${disk} GB"
(( cpus >= 4 )) || note "少于 4 核：能跑，但同时跑两个沙箱会慢"
(( mem >= 3500 )) || note "内存少于 4 GB：Sysbox 建议至少 4 GB"
(( disk >= 20 )) || note "硬盘剩余不到 20 GB：镜像多了会不够"
if (( ok == 0 )); then refund_hint; exit 1; fi
pause "这台机器可以。按回车继续"

# ── 2 ────────────────────────────────────────────────────────────────────
stage "安装 Docker Engine（官方源）"
if command -v snap >/dev/null 2>&1 && snap list docker >/dev/null 2>&1; then
  warn "系统里有 snap 装的 Docker，Sysbox 不支持它。"
  if confirm "删掉 snap 版的 Docker？（新机器上没有要保留的东西）"; then snap remove --purge docker; else exit 1; fi
fi
if command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1; then
  step "已经装好了：$(docker version --format '{{.Server.Version}}')，跳过"
else
  say "从 Docker 的官方源安装，大约一两分钟。"
  apt-get update -q
  apt-get install -y -q ca-certificates curl
  install -m 0755 -d /etc/apt/keyrings
  curl -fsSL https://download.docker.com/linux/ubuntu/gpg -o /etc/apt/keyrings/docker.asc
  chmod a+r /etc/apt/keyrings/docker.asc
  echo "deb [arch=$(dpkg --print-architecture) signed-by=/etc/apt/keyrings/docker.asc] https://download.docker.com/linux/ubuntu ${UBUNTU_CODENAME:-$VERSION_CODENAME} stable" \
    > /etc/apt/sources.list.d/docker.list
  apt-get update -q
  apt-get install -y -q docker-ce docker-ce-cli containerd.io docker-buildx-plugin
  systemctl enable --now docker
  step "装好了：$(docker version --format '{{.Server.Version}}')"
fi
pause "按回车继续"

# ── 3 ────────────────────────────────────────────────────────────────────
stage "安装 Sysbox ${SYSBOX_VERSION}"
if command -v sysbox-runc >/dev/null 2>&1 && systemctl is-active --quiet sysbox; then
  step "已经装好了：$(sysbox-runc --version 2>/dev/null | head -1)，跳过"
else
  say "Sysbox 让沙箱里能再跑 Docker，又不用给沙箱特权。"
  apt-get install -y -q jq fuse3 rsync iptables lsb-release
  tmp=$(mktemp -d)
  curl -fsSL -o "$tmp/sysbox.deb" "$SYSBOX_URL"
  if ! echo "$SYSBOX_SHA256  $tmp/sysbox.deb" | sha256sum -c --quiet -; then
    warn "下载的安装包校验不对，停下来了。把这段输出发给 Claude。"; exit 1
  fi
  step "安装包校验通过"
  if [[ -n "$(docker ps -q)" ]]; then
    warn "安装 Sysbox 会重启 Docker，正在运行的容器会停掉。"
    confirm "继续？" || exit 1
  fi
  apt-get install -y -q "$tmp/sysbox.deb"
  rm -rf "$tmp"
  systemctl is-active --quiet sysbox || { warn "sysbox 服务没起来："; journalctl -u sysbox -n 20 --no-pager; exit 1; }
  step "装好了：$(sysbox-runc --version 2>/dev/null | head -1)"
fi
pause "按回车继续"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "沙箱的存储：每个沙箱一份固定的磁盘额度"
# Docker、containerd、Sysbox 和沙箱自己的数据放到一块开了项目配额（prjquota）的 XFS 上，
# 守护进程才能给每个沙箱设磁盘上限（apps/host/src/sandbox/disk-quota.ts）。系统盘是 ext4 时建一个镜像文件，
# 格式化成 XFS 用 loop 挂上，不用重新分区；四个目录用 bind 挂过去。
STORAGE_IMG="/var/lib/seekcloud-storage.img"
STORAGE_MNT="/srv/seekcloud-storage"
STORAGE_DIRS=(docker containerd sysbox seekcloud)
storage_ready() {
  [[ "$(findmnt -n -o FSTYPE "$STORAGE_MNT" 2>/dev/null)" == "xfs" ]] || return 1
  findmnt -n -o OPTIONS "$STORAGE_MNT" | grep -qE "prjquota|pquota" || return 1
  local d
  for d in "${STORAGE_DIRS[@]}"; do
    [[ "$(findmnt -n -o TARGET --target "/var/lib/$d" 2>/dev/null)" == "/var/lib/$d" ]] || return 1
  done
}
if storage_ready; then
  step "已经配好了：$STORAGE_MNT 是 $(df -h --output=size "$STORAGE_MNT" | tail -1 | xargs) 的 XFS，开了项目配额，跳过"
else
  say "这一步把 Docker、Sysbox 和沙箱的数据搬到一块开了项目配额的 XFS 上，每个沙箱才限得住磁盘。"
  say "系统盘是 ext4，所以建一个镜像文件，格式化成 XFS 再挂上，不用重新分区。"
  warn "Docker、containerd 和 Sysbox 要停一下，已有的容器和镜像会删掉。"
  note "测试机上的镜像下次跑工作流时会重新构建，大约十来分钟。"
  note "先到 GitHub 仓库的 Actions 页面看一眼，没有正在跑的工作流再继续。"
  confirm "继续？" || exit 1
  apt-get install -y -q xfsprogs
  runner_registered=0
  if [[ -f "$RUNNER_DIR/.runner" ]]; then
    runner_registered=1
    (cd "$RUNNER_DIR" && ./svc.sh stop >/dev/null) || true
  fi
  systemctl stop docker.socket docker.service sysbox.service containerd.service
  # 旧的数据（只有测试用的容器和镜像）删掉，腾出地方给镜像文件
  for d in "${STORAGE_DIRS[@]}"; do
    umount -R "/var/lib/$d" 2>/dev/null || true
    rm -rf "/var/lib/$d"
    mkdir -p "/var/lib/$d"
  done
  if [[ ! -f "$STORAGE_IMG" ]]; then
    avail=$(df -BG --output=avail / | tail -1 | tr -dc '0-9')
    # 给系统留 6 GB；镜像文件一次占满（fallocate），不用稀疏文件：宿主机盘满时里面的文件系统不会出 I/O 错
    size=$(( avail - 6 ))
    if (( size < 15 )); then
      warn "硬盘剩余 ${avail} GB，放不下（至少要 21 GB）。"
      systemctl start containerd docker sysbox
      exit 1
    fi
    step "建 ${size} GB 的镜像文件 $STORAGE_IMG"
    fallocate -l "${size}G" "$STORAGE_IMG"
    chmod 600 "$STORAGE_IMG"
    mkfs.xfs -q -f "$STORAGE_IMG"
  fi
  mkdir -p "$STORAGE_MNT"
  # 开机自动挂上：先挂 XFS，再 bind；docker、containerd、sysbox 等挂好了再起
  sed -i '/# seekcloud-storage$/d' /etc/fstab
  echo "$STORAGE_IMG $STORAGE_MNT xfs loop,prjquota,nofail 0 0 # seekcloud-storage" >> /etc/fstab
  for d in "${STORAGE_DIRS[@]}"; do
    echo "$STORAGE_MNT/$d /var/lib/$d none bind,x-systemd.requires-mounts-for=$STORAGE_MNT 0 0 # seekcloud-storage" >> /etc/fstab
  done
  for svc in containerd docker sysbox; do
    mkdir -p "/etc/systemd/system/$svc.service.d"
    printf '[Unit]\nRequiresMountsFor=/var/lib/docker /var/lib/containerd /var/lib/sysbox\n' \
      > "/etc/systemd/system/$svc.service.d/seekcloud-storage.conf"
  done
  systemctl daemon-reload
  findmnt "$STORAGE_MNT" >/dev/null || mount "$STORAGE_MNT"
  for d in "${STORAGE_DIRS[@]}"; do
    mkdir -p "$STORAGE_MNT/$d"
    findmnt "/var/lib/$d" >/dev/null || mount "/var/lib/$d"
  done
  systemctl start containerd docker sysbox
  if ! xfs_quota -x -c "state -p" "$STORAGE_MNT" | grep -q "Enforcement: ON"; then
    warn "项目配额没有生效。把下面这段输出发给 Claude："
    xfs_quota -x -c "state -p" "$STORAGE_MNT" || true
    findmnt "$STORAGE_MNT" || true
    exit 1
  fi
  if ! storage_ready; then
    warn "目录没有挂好。把下面这段输出发给 Claude："
    findmnt --target /var/lib/docker || true
    exit 1
  fi
  if (( runner_registered == 1 )); then (cd "$RUNNER_DIR" && ./svc.sh start >/dev/null) || true; fi
  step "配好了：$STORAGE_MNT 是 $(df -h --output=size "$STORAGE_MNT" | tail -1 | xargs) 的 XFS，开了项目配额"
fi
pause "按回车开始自检"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "自检：Sysbox 容器里再跑 Docker"
say "起一个 Sysbox 容器，在里面起 Docker，再跑 hello-world。大约一分钟。"
docker rm -f "$SELFTEST" >/dev/null 2>&1 || true
docker run --runtime=sysbox-runc -d --name "$SELFTEST" docker:dind >/dev/null
inner=0
for _ in $(seq 1 60); do
  if docker exec "$SELFTEST" sh -c 'DOCKER_HOST=unix:///var/run/docker.sock docker info' >/dev/null 2>&1; then inner=1; break; fi
  sleep 2
done
hello=""
if (( inner == 1 )); then
  hello=$(docker exec "$SELFTEST" sh -c 'DOCKER_HOST=unix:///var/run/docker.sock docker run --rm hello-world' 2>&1 || true)
fi
if [[ "$hello" == *"Hello from Docker"* ]]; then
  uid_map=$(docker exec "$SELFTEST" head -n1 /proc/self/uid_map | xargs)
  step "容器里的 Docker 能跑 hello-world"
  step "用户映射：$uid_map（容器里的 root 映射到宿主机的普通用户）"
  docker rm -f "$SELFTEST" >/dev/null
else
  warn "自检没过。下面是日志，可以整段发给 Claude（里面没有密码）："
  docker logs --tail 30 "$SELFTEST" 2>&1 || true
  journalctl -u sysbox -n 20 --no-pager || true
  docker rm -f "$SELFTEST" >/dev/null 2>&1 || true
  refund_hint
  exit 1
fi
pause "自检通过。按回车继续"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "GitHub：外部贡献者的工作流要先审批"
say "仓库是公开的。这一步防止别人 fork 以后提的 PR 在你的测试机上跑代码。"
say "在手机浏览器里打开："
open_url "https://github.com/${REPO}/settings/actions"
step "往下找到 \"Fork pull request workflows from outside collaborators\" 这一栏"
step "选 \"Require approval for all outside collaborators\""
step "点这一栏下面的 Save"
pause "改好了按回车（以前运行这个脚本时已经改过的，直接按回车）"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "注册成仓库的 GitHub Runner"
if [[ -f "$RUNNER_DIR/.runner" ]]; then
  step "已经注册过了，跳过"
  (cd "$RUNNER_DIR" && ./svc.sh status | grep -E "Active:" || true)
else
  say "Runner 用单独的系统用户 ${RUNNER_USER} 跑，只连 GitHub，不装也不登录 Claude 的任何东西。"
  note "${RUNNER_USER} 在 docker 组里，等于这台机器的 root：这是专门的测试机，所以可以。"
  confirm "开始注册？" || exit 1
  id "$RUNNER_USER" >/dev/null 2>&1 || useradd -m -s /bin/bash "$RUNNER_USER"
  usermod -aG docker "$RUNNER_USER"
  install -d -o "$RUNNER_USER" -g "$RUNNER_USER" "$RUNNER_DIR"
  release=$(curl -fsSL https://api.github.com/repos/actions/runner/releases/latest)
  pick='.assets[] | select(.name | test("^actions-runner-linux-x64-[0-9.]+\\.tar\\.gz$"))'
  url=$(jq -r "$pick | .browser_download_url" <<<"$release")
  digest=$(jq -r "$pick | .digest // empty" <<<"$release")
  curl -fsSL -o /tmp/actions-runner.tar.gz "$url"
  if [[ "$digest" == sha256:* ]]; then
    echo "${digest#sha256:}  /tmp/actions-runner.tar.gz" | sha256sum -c --quiet - || { warn "Runner 安装包校验不对，停下来了"; exit 1; }
    step "Runner 安装包校验通过"
  fi
  tar -xzf /tmp/actions-runner.tar.gz -C "$RUNNER_DIR"
  rm -f /tmp/actions-runner.tar.gz
  chown -R "$RUNNER_USER:$RUNNER_USER" "$RUNNER_DIR"
  "$RUNNER_DIR/bin/installdependencies.sh" >/dev/null

  say "在手机浏览器里打开下面的页面（要用你的 GitHub 账号登录）："
  open_url "https://github.com/${REPO}/settings/actions/runners/new?arch=x64&os=linux"
  step "页面上 Configure 那一段里有一行 ./config.sh --url … --token …"
  step "只复制 --token 后面那一串（A 开头，大约 29 个字符），不要复制整行"
  note "令牌一小时内有效，只在这台机器上用，不要发给任何人（包括 Claude）。"
  ask_secret RUNNER_TOKEN "粘贴令牌（输入时看不见）："
  (cd "$RUNNER_DIR" && sudo -u "$RUNNER_USER" ./config.sh --unattended \
    --url "https://github.com/${REPO}" --token "$RUNNER_TOKEN" \
    --name "seekcloud-test-$(hostname)" --labels sysbox --work _work --replace)
  unset RUNNER_TOKEN
  (cd "$RUNNER_DIR" && ./svc.sh install "$RUNNER_USER" >/dev/null && ./svc.sh start >/dev/null)
  step "Runner 已经注册并作为系统服务启动了"
fi
say "打开下面的页面，应该能看到 seekcloud-test-… 显示为 Idle："
open_url "https://github.com/${REPO}/settings/actions/runners"
pause "看到了按回车"

finish
say "全部完成。回到 Claude 说一句\"测试机装好了\"。"
printf '\n'
}

run_wizard "$@"; exit
